from pathlib import Path
import json,base64,io,html,re
from PIL import Image
root=Path(__file__).resolve().parent
initial=json.loads((root/'initial-scores.json').read_text())
rerank=json.loads((root/'reranked-scores.json').read_text()) if (root/'reranked-scores.json').exists() else None
for score_set in (initial,rerank):
    if score_set:
        by_file={f['file']:f for f in score_set['files']}
        score_set['files']=[{**by_file[f['duplicate_of']],**f} if f.get('duplicate_of') else f for f in score_set['files']]
shots=[]
for p in sorted((root/'screenshots').glob('*.png')):
    if re.search(r'-(?:before|after)-',p.name) is None: continue
    with Image.open(p) as im:
        size=im.size
        im=im.convert('RGB');im.thumbnail((1080,1200))
        b=io.BytesIO();im.save(b,format='WEBP',quality=86)
    product=p.name.split('-')[0]
    stage=re.search(r'-(\d\d)-',p.name)
    shots.append({'file':p.name,'product':product,'stage':stage.group(1) if stage else '00','state':'after' if '-after-' in p.name else 'before','theme':(re.search(r'-(light|dark|nord|cyber|paper|oled|patina)(?:-full)?$',p.stem).group(1) if re.search(r'-(light|dark|nord|cyber|paper|oled|patina)(?:-full)?$',p.stem) else 'unspecified'),'device':'mobile' if 'mobile' in p.stem else 'desktop','src':'data:image/webp;base64,'+base64.b64encode(b.getvalue()).decode(),'size':size})
# The document embeds every resource. Private original screenshots are never copied into it.
data=json.dumps({'initial':initial,'rerank':rerank,'shots':shots},ensure_ascii=False).replace('<','\\u003c')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ky UI council · comparisons and staged screenshots</title><style>
:root{color-scheme:light;--paper:#f8f6f0;--ink:#182326;--muted:#566461;--panel:#fff;--line:#a2aaa7;--accent:#bf3f18;--onaccent:#fff;font-family:system-ui,sans-serif}
@media(prefers-color-scheme:dark){:root{color-scheme:dark;--paper:#182326;--ink:#f2efe8;--muted:#b3bcb8;--panel:#1f2b2e;--line:#81918d;--accent:#f5865f;--onaccent:#182326}}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-size:.9375rem;line-height:1.5}main{max-width:100rem;margin:auto;padding:2rem}h1{font-size:1.5rem;line-height:1.2;margin:0 0 .75rem;font-weight:650}h2{font-size:1.125rem;margin:2rem 0 .75rem}p{max-width:84ch;margin:.5rem 0;color:var(--muted)}nav,.filters{display:flex;flex-wrap:wrap;gap:.5rem;align-items:end;margin:1.25rem 0}button,select{font:inherit;min-height:2.5rem;border:1px solid var(--line);border-radius:.5rem;padding:.45rem .8rem;background:var(--panel);color:var(--ink)}button{cursor:pointer}button[aria-pressed=true]{background:var(--accent);color:var(--onaccent);border-color:var(--accent)}:focus-visible{outline:2px solid var(--accent);outline-offset:3px}label{display:grid;gap:.25rem;font-size:.8125rem}label select{font-size:.9375rem}section[hidden]{display:none}.compare{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.5rem;align-items:start}figure{min-width:0;margin:0}figure img{display:block;width:100%;height:auto;border:1px solid var(--line);border-radius:.5rem;cursor:zoom-in}figcaption{font-size:.8125rem;color:var(--muted);padding:.5rem 0;overflow-wrap:anywhere}.empty{padding:2rem;border:1px dashed var(--line);border-radius:.5rem}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:.875rem}th,td{text-align:left;padding:.7rem .65rem;border-bottom:1px solid var(--line);vertical-align:top}th{font-weight:650}td.num{font-variant-numeric:tabular-nums;white-space:nowrap}.note{border-top:1px solid var(--line);padding-top:1rem;margin-top:1.5rem}dialog{width:min(94vw,110rem);max-height:94vh;background:var(--panel);color:var(--ink);border:1px solid var(--line);border-radius:.5rem;padding:1rem}dialog::backdrop{background:#0009}dialog img{width:100%;height:auto}dialog button{position:sticky;top:0;float:right}.file-list{display:grid;gap:.25rem;font-size:.8125rem;color:var(--muted)}@media(max-width:650px){main{padding:1rem}.compare{grid-template-columns:1fr}th,td{padding:.55rem .4rem}.filters label{flex:1 1 40%}.filters select{width:100%}}
</style><main><h1>Ky UI council</h1><p>Refining the Busnes identity across KyPost, KyCalendar and KyMessages. The goal is 9/10; the evidence decides the score.</p><nav aria-label="Report"><button id="view-screens" aria-pressed="true">Staged screenshots</button><button id="view-ratings" aria-pressed="false">Competitive ratings</button><button id="view-method" aria-pressed="false">Evidence and limits</button></nav><section id="screens"><div class="filters"><label>Product<select id="product"><option value="kypost">KyPost</option><option value="kycalendar">KyCalendar</option><option value="kymessages">KyMessages console</option></select></label><label>Stage<select id="stage"><option value="00">Baseline</option><option value="01">1 · Shell</option><option value="02">2 · Task views</option><option value="03">3 · Forms and dialogs</option><option value="04">4 · Calendar single sidebar</option><option value="05">5 · Usability refinements</option><option value="06">6 · Review corrections</option></select></label><label>Theme<select id="theme"><option value="light">Busnes Light</option><option value="dark">Busnes Dark</option></select></label><label>Screen size<select id="device"><option value="desktop">Desktop</option><option value="mobile">Phone</option></select></label><label>Surface<select id="surface"></select></label></div><p id="capture-note"></p><div id="images" class="compare"></div><p class="note">Tap a screenshot to enlarge it. These are real disposable application instances with synthetic content. The initial baseline uses the recorded local revisions; fresh stage captures identify the current before/after sources. KyMessages console screenshots do not establish Element chat quality.</p></section><section id="ratings" hidden><div class="filters"><label>Round<select id="round"><option value="initial">Initial review</option><option value="rerank">Improved rubric</option></select></label><label>Surface cohort<select id="cohort"></select></label></div><p id="rating-note"></p><div class="scroll"><table><thead><tr><th scope="col">Captured product</th><th scope="col">Surface / file</th><th scope="col">Score / 10</th><th scope="col">Evidence caveat</th></tr></thead><tbody id="rows"></tbody></table></div><p class="note">All 40 original files are accounted for, including one near duplicate. Calendar views and editors use separate cohorts in the improved rubric. Scores describe the supplied screenshots, with differing content, themes and client generations; they do not prove functionality or accessibility. Ky brand fit is separate from competitive quality.</p></section><section id="method" hidden><h2>What the two rounds establish</h2><p>Claude Opus 5.5 first rated every supplied image, authored the Ky suite UI skill, then a fresh review used its fixed anchors and matched cohorts. Re-scoring unchanged originals measures a method change. Only new before/after implementation captures show design changes.</p><h2>Shared design contract</h2><p>Keep the cream and charcoal palette with restrained orange. Use the self-hosted Space Grotesk, shared type and spacing tokens, calm full-bleed task views, clear primary/secondary/destructive actions, accessible controls and consistent navigation. Preserve product roles, security boundaries, named themes and saved choices.</p><h2>What 9/10 needs</h2><p>Reviewed current screens plus recorded keyboard, focus, contrast, responsive and empty/loading/error evidence. Missing evidence stays untested. No score is raised to satisfy a target.</p><h2>Delivery limits</h2><p>No production deployment, merge or fleet-wide rollout is implied. Shared 0.3.0 is pending; public consumer branches still use the earlier copy. MySlop rejected its configured token with HTTP 401, so its handoff was not posted. Private originals remain outside this report.</p><h2>Source records</h2><div class="file-list"><span>initial-review.md · initial-scores.json</span><span>reranked-review.md · reranked-scores.json</span><span>baseline-capture-notes.md · verification.md</span><span>Product implementation notes and source patches accompany staged screenshots.</span></div></section></main><dialog id="zoom" aria-label="Enlarged screenshot"><button id="close-zoom">Close</button><img alt=""></dialog><script type="application/json" id="report-data">__DATA__</script><script>
const D=JSON.parse(document.getElementById('report-data').textContent);const $=id=>document.getElementById(id);const text=(el,value)=>{el.textContent=value};
for(const [name,id] of [['screens','view-screens'],['ratings','view-ratings'],['method','view-method']])$(id).addEventListener('click',()=>{for(const n of ['screens','ratings','method']){$(n).hidden=n!==name;$('view-'+n).setAttribute('aria-pressed',String(n===name))}});
function candidates(){return D.shots.filter(x=>x.product===$('product').value&&x.stage===$('stage').value&&x.theme===$('theme').value&&x.device===$('device').value)}
function surface(x){return x.file.replace(new RegExp('^'+x.product+'-\\\\d\\\\d-(before|after)-'),'').replace(/-(desktop|mobile|light|dark|current)(?=\\\\.|-)/g,'').replace(/\\\\.png$/,'')}
function choose(){const list=candidates();const names=[...new Set(list.map(surface))];$('surface').replaceChildren(...names.map(v=>{const o=document.createElement('option');o.value=v;o.textContent=v.replaceAll('-',' ');return o}));show()}
function show(){const list=candidates().filter(x=>surface(x)===$('surface').value).sort((a,b)=>Number(a.state==='after')-Number(b.state==='after'));const images=$('images');images.replaceChildren();if(!list.length){const d=document.createElement('p');d.className='empty';text(d,'No capture is recorded for this combination.');images.append(d);text($('capture-note'),'Missing evidence is shown explicitly.');return}text($('capture-note'),`Stage ${$('stage').value} · ${$('theme').value} · ${$('device').value}`);for(const x of list){const f=document.createElement('figure');const c=document.createElement('figcaption');text(c,`${x.state==='before'?'Before':'After'} · ${x.size.join(' × ')} · ${x.file}`);const img=document.createElement('img');img.src=x.src;img.alt=x.file.replaceAll('-',' ');img.loading='lazy';img.tabIndex=0;const open=()=>{$('zoom').querySelector('img').src=x.src;$('zoom').querySelector('img').alt=img.alt;$('zoom').showModal()};img.addEventListener('click',open);img.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();open()}});f.append(c,img);images.append(f)}}
for(const t of [...new Set(D.shots.map(x=>x.theme))])if(![...$('theme').options].some(o=>o.value===t)){const o=document.createElement('option');o.value=t;o.textContent=t;$('theme').append(o)};for(const id of ['product','stage','theme','device'])$(id).addEventListener('change',choose);$('surface').addEventListener('change',show);$('close-zoom').addEventListener('click',()=>$('zoom').close());
function round(){return $('round').value==='rerank'?D.rerank:D.initial}
function cohorts(){const r=round();const names=r?[...new Set(r.files.map(x=>x.cohort))].sort():[];$('cohort').replaceChildren(...names.map(v=>{const o=document.createElement('option');o.value=v;o.textContent=v.replaceAll('-',' ');return o}));ratings()}
function ratings(){const r=round();$('rows').replaceChildren();if(!r){text($('rating-note'),'Improved-rubric results are not yet recorded.');return}text($('rating-note'),`Claude Opus 5.5 · ${$('round').value==='rerank'?'Improved rubric; unchanged original screenshots':'Initial rubric'} · duplicate captures excluded from ranking`);for(const x of r.files.filter(x=>x.cohort===$('cohort').value&&!x.duplicate_of).sort((a,b)=>b.total-a.total)){const tr=document.createElement('tr');for(const [i,v] of [x.observed_product,(x.observed_surface||'')+' · '+x.file,Number(x.total).toFixed(1),x.caveat||''].entries()){const td=document.createElement('td');if(i===2)td.className='num';text(td,v);tr.append(td)}$('rows').append(tr)}}
$('round').addEventListener('change',cohorts);$('cohort').addEventListener('change',ratings);choose();cohorts();
</script></html>'''
page=page.replace('__DATA__',data)
# Repair JS regex escapes after template interpolation; there is no user HTML interpolation.
page=page.replace('\\\\d','\\d').replace('\\\\.','\\.')
(root/'council.html').write_text(page)
print('Wrote',root/'council.html','with',len(shots),'synthetic screenshot previews; bytes',len(page.encode()))
